import os
from typing import Dict, Any
import boto3
from botocore.exceptions import ClientError

def normalize_expense(image_path: str) -> Dict[str, Any]:
    """
    Extract and normalize expense fields from an image using AWS Textract AnalyzeExpense.

    Args:
        image_path: Path to the image file (JPEG, PNG, PDF).

    Returns:
        Dictionary with normalized expense fields.
    """
    client = boto3.client('textract', region_name='us-east-1')

    with open(image_path, 'rb') as image_file:
        image_bytes = image_file.read()

    try:
        response = client.analyze_expense(Document={'Bytes': image_bytes})
    except ClientError as e:
        raise RuntimeError(f"AWS Textract API error: {e}")

    normalized = {
        "vendor_name": "",
        "invoice_date": "",
        "invoice_number": "",
        "total_amount": 0.0,
        "tax_amount": 0.0,
        "currency": "USD",
        "line_items": []
    }

    if 'ExpenseDocuments' not in response or not response['ExpenseDocuments']:
        return normalized

    expense_doc = response['ExpenseDocuments'][0]

    summary_fields = expense_doc.get('SummaryFields', [])
    for field in summary_fields:
        label = field.get('Type', {}).get('Text', '').lower()
        value_text = field.get('ValueDetection', {}).get('Text', '')

        if 'vendor' in label or 'seller' in label:
            normalized["vendor_name"] = value_text
        elif 'invoice date' in label or 'date' in label:
            normalized["invoice_date"] = value_text
        elif 'invoice number' in label or 'receipt id' in label:
            normalized["invoice_number"] = value_text
        elif 'total' in label and 'tax' not in label:
            try:
                normalized["total_amount"] = float(value_text.replace('$', '').replace(',', ''))
            except ValueError:
                pass
        elif 'tax' in label:
            try:
                normalized["tax_amount"] = float(value_text.replace('$', '').replace(',', ''))
            except ValueError:
                pass
        elif 'currency' in label:
            normalized["currency"] = value_text

    line_item_groups = expense_doc.get('LineItemGroups', [])
    for group in line_item_groups:
        for item in group.get('LineItems', []):
            line_item = {}
            for field in item.get('LineItemExpenseFields', []):
                label = field.get('Type', {}).get('Text', '').lower()
                value_text = field.get('ValueDetection', {}).get('Text', '')

                if 'item' in label or 'description' in label:
                    line_item["description"] = value_text
                elif 'quantity' in label:
                    try:
                        line_item["quantity"] = float(value_text)
                    except ValueError:
                        pass
                elif 'unit price' in label:
                    try:
                        line_item["unit_price"] = float(value_text.replace('$', '').replace(',', ''))
                    except ValueError:
                        pass
                elif 'amount' in label:
                    try:
                        line_item["amount"] = float(value_text.replace('$', '').replace(',', ''))
                    except ValueError:
                        pass

            if line_item:
                normalized["line_items"].append(line_item)

    return normalized
